package com.citacloud.app.controllers;
import com.citacloud.app.security.*; import com.citacloud.app.services.OrdenEstudioService; import jakarta.annotation.security.PermitAll; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@RestController @RequestMapping("/ordenes-estudios") @PermitAll public class OrdenPdfController {private final OrdenEstudioService ordenes;public OrdenPdfController(OrdenEstudioService ordenes){this.ordenes=ordenes;}@GetMapping(value="/{id}/pdf",produces=MediaType.APPLICATION_PDF_VALUE) public ResponseEntity<byte[]> pdf(@PathVariable UUID id){TenantUserDetails u=AuthService.getAuthenticatedUser();if(u==null)return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).body(ordenes.generarPdfJasper(u.getEmpresaId(),id));}}
